@php($rounds = $tournament->matches->groupBy('round'))
@if($rounds->isEmpty())<p>Сетка ещё не сформирована.</p>@else<div class="bracket" aria-label="Турнирная сетка">@foreach($rounds as $round => $matches)<section class="bracket__round"><h3>{{ $loop->last ? 'Финал' : 'Раунд '.$round }}</h3><div class="bracket__matches">@foreach($matches as $match)<article class="bracket-match"><header><span>Матч {{ $match->position }}</span><small>{{ ['pending' => 'Ожидает соперников', 'scheduled' => 'Запланирован', 'live' => 'Идёт сейчас', 'finished' => 'Завершён'][$match->matchStatus] ?? '' }}</small></header>@foreach(['A','B'] as $side)@php($team = $match->{'team'.$side})<div class="{{ $team && $match->winner?->id === $team->id ? 'bracket-match__winner' : '' }}">@if($team)<a href="/teams/{{ $team->documentId }}">{{ $team->name }}@if($match->winner?->id === $team->id)<span class="bracket-result">Победа</span>@endif</a>@else<span>Ожидается</span>@endif<strong>{{ $match->{'score'.$side} ?? '—' }}</strong></div>@endforeach</article>@endforeach</div></section>@endforeach</div>@endif
